{
  "question": "Iran closes its airspace by June 15?",
  "factors": [
    {
      "factor": "Current geopolitical tensions and military posture",
      "direction": "supports_yes",
      "weight": "high",
      "evidence": "Iran has been in a heightened state of alert since early 2026, with periodic airspace closures (e.g., January 2026 total closure). Recent Israeli airstrikes on Iranian nuclear facilities in May 2026 have increased risk of retaliatory or defensive closures."
    },
    {
      "factor": "Historical frequency of major airspace closures",
      "direction": "supports_no",
      "weight": "high",
      "evidence": "Since 2024, Iran has closed its airspace broadly only twice (April 2024 and January 2026) in response to specific military crises. Such closures are rare and typically last hours to days, not sustained over weeks."
    },
    {
      "factor": "Time remaining and trigger probability",
      "direction": "supports_no",
      "weight": "medium",
      "evidence": "Only 8 days remain. A major closure requires a proximate trigger (e.g., imminent attack, large-scale military exercise, or internal crisis). No such trigger is publicly evident as of June 7, 2026."
    },
    {
      "factor": "Economic and diplomatic costs",
      "direction": "supports_no",
      "weight": "medium",
      "evidence": "Iran relies on overflight fees and international connectivity. A prolonged closure would harm its economy and isolate it further. Previous closures were brief and targeted."
    },
    {
      "factor": "Internal political stability",
      "direction": "neutral",
      "weight": "low",
      "evidence": "No major internal unrest or regime-threatening protests reported in recent weeks. Stability reduces likelihood of a closure for domestic reasons."
    }
  ],
  "baseRate": {
    "value": 0.08,
    "reasoning": "Over the past 2.5 years (since April 2024), Iran has initiated a major airspace closure roughly 2 times in ~30 months, or about 0.8 per year. In any given 8-day window, the base rate is approximately 8% (2 closures / 912 days * 8 days)."
  },
  "adjustments": [
    {
      "reason": "Elevated military tensions in May-June 2026 due to Israeli strikes",
      "delta": 0.05,
      "evidence": "Post-strike environment increases probability of defensive or retaliatory closures, but no immediate escalation observed."
    },
    {
      "reason": "Market price of 7.2% suggests informed traders see low risk; no new crisis indicators",
      "delta": -0.02,
      "evidence": "While I avoid anchoring, the market's low price aligns with base rate and lack of trigger. I slightly discount for absence of recent credible threats."
    }
  ],
  "finalEstimate": 0.11,
  "confidence": "medium",
  "confidenceInterval": [0.03, 0.25],
  "keyUncertainties": [
    "A sudden military escalation (e.g., Israeli or US strike on Iran) could trigger a closure within hours.",
    "Internal unrest or a major accident (e.g., plane crash) could prompt a precautionary closure.",
    "Diplomatic breakthroughs could reduce tension further, lowering probability to near zero."
  ],
  "researchNeeded": [
    "Monitor Iranian state media and FlightRadar24 for any signs of airspace restrictions.",
    "Track Israeli and US military movements in the region.",
    "Check for any recent NOTAMs (Notices to Air Missions) from Iran."
  ],
  "reasoning": "The base rate for an 8-day window is low (~8%), reflecting that major airspace closures are rare events triggered by acute crises. While current geopolitical tensions are elevated following Israeli strikes in May, no immediate trigger for a closure exists as of June 7. The market price of 7.2% is consistent with this base rate, suggesting traders are not pricing in a high probability of a sudden escalation. However, the fat-tail risk of a rapid military confrontation (e.g., a retaliatory strike by Iran or a preemptive US/Israeli action) could push probability higher. I estimate an 11% chance, slightly above base rate due to the tense environment, but still low because closures require a proximate cause and have significant economic costs for Iran. The confidence interval is wide because a single news event could dramatically change the outlook within the remaining 8 days."
